CREATE TABLE "mbbs_categories" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" TEXT COLLATE NOCASE NOT NULL, "privacy" TEXT COLLATE NOCASE NOT NULL, "created_by" INTEGER NOT NULL, "created_at" TEXT COLLATE NOCASE NOT NULL, "comments" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "mbbs_categories_entries_relation" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "category_id" INTEGER NOT NULL, "entry_id" INTEGER NOT NULL, "created_at" TEXT COLLATE NOCASE NOT NULL, "created_by" INTEGER NOT NULL);

CREATE TABLE "mbbs_comments" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "original_post_id" INTEGER NOT NULL, "body" TEXT COLLATE NOCASE NOT NULL, "comment_by" INTEGER NOT NULL, "timestamp" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "mbbs_deleted_entries" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "heading" TEXT COLLATE NOCASE NOT NULL, "body" TEXT COLLATE NOCASE NOT NULL, "comment_by" INTEGER NOT NULL, "timestamp" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "mbbs_entries" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "heading" TEXT COLLATE NOCASE NOT NULL, "body" TEXT COLLATE NOCASE NOT NULL, "comment_by" INTEGER NOT NULL DEFAULT '1', "timestamp" TEXT COLLATE NOCASE);

CREATE TABLE "mbbs_updates" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "entry_id" INTEGER NOT NULL, "old_heading" TEXT COLLATE NOCASE NOT NULL, "old_body" TEXT COLLATE NOCASE NOT NULL, "updated_by_id" INTEGER NOT NULL, "datetime" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "mbbs_users" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" TEXT COLLATE NOCASE NOT NULL, "roll" INTEGER NOT NULL, "phone" INTEGER NOT NULL, "email" TEXT COLLATE NOCASE NOT NULL);
